#!/usr/bin/env python3
"""
rag_metadata_system.py
======================

A self-contained Retrieval-Augmented Generation (RAG) system that uses
document **metadata** both to *filter* the candidate set and to *rank*
documents by relevance to a user query.

Design overview
---------------
1. Indexing
   - Documents are split into chunks (RecursiveChunker below) and each
     chunk carries metadata (source, category, tags, published_at, ...).
   - A sparse TF-IDF vector index (pure standard library + math) stores
     semantic vectors. The ``Embedder`` interface allows swapping in a
     dense embedder (e.g. sentence-transformers) without touching the
     rest of the pipeline.

2. Retrieval (metadata filtering)
   - ``MetadataFilters`` express equality / membership constraints,
     exclusion constraints, and inclusive ranges over metadata fields.
     Filters narrow the corpus *before* scoring.

3. Ranking (metadata-aware relevance)
   - ``RelevanceRanker`` combines:
       * semantic score: cosine similarity between the query vector and
         each candidate vector, and
       * metadata score: a weighted blend of rules that are evaluated
         against the *query* (e.g. tag overlap with query keywords,
         recency of the document, priority of its source/category).
     The final ranking is ``w_sem * semantic + w_meta * metadata``.
   - Optional Maximal Marginal Relevance (MMR) re-ranking adds diversity.

4. Generation
   - A grounded prompt is assembled from the retrieved contexts (with
     metadata citations) and passed to a pluggable, injectable
     ``llm_fn``. Nothing is generated when no LLM function is supplied.

Safety / locality
-----------------
This implementation is fully local: it performs **no network I/O**, makes
no external HTTP calls, and never transmits user queries or document text
anywhere outside the process. Metadata ranking rules are supplied by the
caller through the public API below.

Run the demo (no third-party dependencies):

    python3 rag_metadata_system.py
"""

from __future__ import annotations

import math
import re
import unicodedata
from collections import Counter
from dataclasses import dataclass, field
from datetime import date, datetime
from typing import (
    Any,
    Callable,
    Dict,
    Iterable,
    List,
    Mapping,
    Optional,
    Sequence,
    Set,
    Tuple,
)

# ---------------------------------------------------------------------------
# Text utilities
# ---------------------------------------------------------------------------

_DEFAULT_STOPWORDS: Set[str] = {
    "a", "an", "and", "are", "as", "at", "be", "but", "by", "can", "for",
    "from", "has", "have", "how", "in", "is", "it", "its", "not", "of",
    "on", "or", "our", "that", "the", "this", "to", "was", "we", "what",
    "when", "where", "which", "will", "with", "you", "your",
}


def normalize_text(text: Any) -> str:
    """Lowercase + Unicode-normalize text for stable comparisons."""
    return unicodedata.normalize("NFKC", str(text)).lower()


def tokenize(text: Any, stopwords: Optional[Set[str]] = None) -> List[str]:
    """Return meaningful word/digit tokens from *text*."""
    if text is None:
        return []
    if stopwords is None:
        stopwords = _DEFAULT_STOPWORDS
    raw = re.findall(r"[\w]+", unicodedata.normalize("NFKC", str(text)).lower())
    return [tok for tok in raw if len(tok) > 1 and tok not in stopwords]


def _to_date(value: Any) -> Optional[date]:
    """Best-effort conversion of ISO dates/datetimes/datetime objects."""
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None:
        return None
    try:
        return datetime.strptime(str(value)[:10], "%Y-%m-%d").date()
    except ValueError:
        return None


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------

@dataclass
class Document:
    """A text chunk plus its metadata."""

    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    doc_id: Optional[str] = None

    def __post_init__(self) -> None:
        if self.doc_id is None:
            self.doc_id = f"doc-{abs(hash(self.text)):x}"


@dataclass
class RecursiveChunker:
    """Split long texts into overlapping chunks, carrying metadata forward."""

    chunk_size: int = 900
    chunk_overlap: int = 120

    def split(self, text: str, metadata: Optional[Mapping[str, Any]] = None) -> List[Document]:
        meta: Dict[str, Any] = dict(metadata or {})
        if not text:
            return []
        size, overlap = self.chunk_size, self.chunk_overlap
        step = max(1, size - overlap)
        chunks: List[Document] = []
        for start in range(0, len(text), step):
            piece = text[start : start + size].strip()
            if not piece:
                continue
            if start > 0 and len(piece) < max(1, overlap // 2):
                break  # trailing sliver that is mostly overlap
            chunk_meta = dict(meta)
            chunk_meta.setdefault("chunk_index", len(chunks))
            chunks.append(Document(text=piece, metadata=chunk_meta))
        return chunks


# ---------------------------------------------------------------------------
# Sparse vector index (TF-IDF cosine similarity)
# ---------------------------------------------------------------------------

def _dot(a: Mapping[str, float], b: Mapping[str, float]) -> float:
    """Dot product iterating over the smaller mapping."""
    if not a or not b:
        return 0.0
    if len(a) > len(b):
        a, b = b, a
    return sum(av * b.get(t, 0.0) for t, av in a.items())


class DocumentIndex:
    """In-memory TF-IDF index over Documents with metadata."""

    def __init__(self) -> None:
        self.docs: List[Document] = []
        self._raw: List[Counter] = []
        self._df: Counter = Counter()
        self._idf: Dict[str, float] = {}
        self._vectors: List[Dict[str, float]] = []
        self._pos: Dict[int, int] = {}  # id(doc) -> position
        self._built = False

    # -- indexing -----------------------------------------------------------
    def add(self, document: Document) -> "DocumentIndex":
        counts = Counter(tokenize(document.text))
        self._pos[id(document)] = len(self.docs)
        self.docs.append(document)
        self._raw.append(counts)
        for term in counts:
            self._df[term] += 1
        self._built = False
        return self

    def add_many(self, documents: Iterable[Document]) -> "DocumentIndex":
        for doc in documents:
            self.add(doc)
        return self

    def build(self) -> None:
        n = len(self.docs)
        if n == 0:
            self._built = True
            return
        for term, df in self._df.items():
            # BM25-style idf, smoothed so even very frequent terms get a push.
            self._idf[term] = math.log((n - df + 0.5) / (df + 0.5) + 1.0) + 1.0
        self._vectors = []
        for counts in self._raw:
            vec = {t: self._idf[t] * c for t, c in counts.items() if t in self._idf}
            norm = math.sqrt(sum(v * v for v in vec.values()))
            self._vectors.append({t: v / norm for t, v in vec.items()} if norm > 0 else {})
        self._built = True

    def _ensure_built(self) -> None:
        if not self._built:
            self.build()

    # -- query side ---------------------------------------------------------
    def query_vector(self, text: str) -> Dict[str, float]:
        self._ensure_built()
        counts = Counter(tokenize(text))
        if not counts or not self._idf:
            return {}
        default_idf = max(self._idf.values()) if self._idf else 1.0
        vec = {t: self._idf.get(t, default_idf) * c for t, c in counts.items()}
        norm = math.sqrt(sum(v * v for v in vec.values()))
        return {t: v / norm for t, v in vec.items()} if norm > 0 else {}

    def vector_for(self, document: Document) -> Dict[str, float]:
        self._ensure_built()
        idx = self._pos.get(id(document))
        return self._vectors[idx] if idx is not None else {}

    def similarity(self, query_text: str, document: Document) -> float:
        return _dot(self.query_vector(query_text), self.vector_for(document))


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------

@dataclass
class MetadataFilters:
    """Declarative filters applied against document metadata.

    * include:  field -> sequence of accepted values (equality / membership)
    * exclude:  field -> sequence of values to reject
    * ranges:   field -> (low, high) inclusive bounds; None means open.
                Numeric fields compare numerically; ISO date strings compare
                lexicographically (correct for ISO-8601).
    """

    include: Dict[str, Sequence[Any]] = field(default_factory=dict)
    exclude: Dict[str, Sequence[Any]] = field(default_factory=dict)
    ranges: Dict[str, Tuple[Optional[Any], Optional[Any]]] = field(default_factory=dict)

    @property
    def empty(self) -> bool:
        return not (self.include or self.exclude or self.ranges)

    @staticmethod
    def _values(metadata: Mapping[str, Any], field_name: str) -> List[str]:
        value = metadata.get(field_name)
        if value is None:
            return []
        if isinstance(value, (list, tuple, set)):
            return [str(v) for v in value]
        return [str(value)]

    @staticmethod
    def _norm(value: Any) -> str:
        return unicodedata.normalize("NFKC", str(value)).strip().lower()

    @staticmethod
    def _in_range(value_str: str, low: Optional[Any], high: Optional[Any]) -> bool:
        try:
            value = float(value_str)
            if low is not None and value < float(low):
                return False
            if high is not None and value > float(high):
                return False
            return True
        except (TypeError, ValueError):
            if low is not None and value_str < str(low):
                return False
            if high is not None and value_str > str(high):
                return False
            return True

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        if self.empty:
            return True
        for field_name, accepted in self.include.items():
            accepted_norm = {self._norm(a) for a in accepted}
            if not any(self._norm(v) in accepted_norm for v in self._values(metadata, field_name)):
                return False
        for field_name, blocked in self.exclude.items():
            blocked_norm = {self._norm(b) for b in blocked}
            if any(self._norm(v) in blocked_norm for v in self._values(metadata, field_name)):
                return False
        for field_name, (low, high) in self.ranges.items():
            values = self._values(metadata, field_name)
            if not values or not any(self._in_range(v, low, high) for v in values):
                return False
        return True

    def apply(self, documents: Sequence[Document]) -> List[Document]:
        return [doc for doc in documents if self.matches(doc.metadata)]


# ---------------------------------------------------------------------------
# Metadata relevance rules (query-aware scoring)
# ---------------------------------------------------------------------------

class Rule:
    """Base class for a metadata ranking rule.

    ``score`` returns a value in [0, 1]; higher is more relevant. Rules are
    evaluated against the user query so ranking is query-aware.
    """

    def __init__(self, weight: float = 1.0) -> None:
        if weight <= 0:
            raise ValueError("rule weight must be > 0")
        self.weight = weight

    def score(self, metadata: Mapping[str, Any], query_tokens: Set[str]) -> float:
        raise NotImplementedError


class TagOverlapRule(Rule):
    """Boost documents whose metadata tags overlap the query's keywords."""

    def __init__(self, field: str = "tags", weight: float = 1.0) -> None:
        super().__init__(weight=weight)
        self.field = field

    def score(self, metadata: Mapping[str, Any], query_tokens: Set[str]) -> float:
        if not query_tokens:
            return 0.0
        raw = metadata.get(self.field)
        if not raw:
            return 0.0
        values = raw if isinstance(raw, (list, tuple, set)) else [raw]
        tag_tokens: Set[str] = set()
        for value in values:
            tag_tokens.update(tokenize(value))
        if not tag_tokens:
            return 0.0
        overlap = len(query_tokens & tag_tokens)
        return min(1.0, overlap / max(1, len(query_tokens)))


class RecencyRule(Rule):
    """Exponentially decay relevance for documents older than *half_life_days*."""

    def __init__(
        self,
        date_field: str = "published_at",
        half_life_days: float = 730.0,
        unknown_score: float = 0.4,
        weight: float = 1.0,
    ) -> None:
        super().__init__(weight=weight)
        self.date_field = date_field
        self.half_life_days = float(half_life_days)
        self.unknown_score = float(unknown_score)

    def score(self, metadata: Mapping[str, Any], query_tokens: Set[str]) -> float:
        value = _to_date(metadata.get(self.date_field))
        if value is None:
            return self.unknown_score
        age_days = max(0, (date.today() - value).days)
        return math.exp(-age_days / self.half_life_days)


class ValuePriorityRule(Rule):
    """Assign a priority score to exact metadata field values.

    Example: source=official_document -> 1.0, source=third_party -> 0.2.
    """

    def __init__(
        self,
        field: str,
        priorities: Mapping[Any, float],
        default: float = 0.0,
        weight: float = 1.0,
    ) -> None:
        super().__init__(weight=weight)
        self.field = field
        self.priorities = {self._norm(k): float(v) for k, v in priorities.items()}
        self.default = float(default)

    @staticmethod
    def _norm(value: Any) -> str:
        return unicodedata.normalize("NFKC", str(value)).strip().lower()

    def score(self, metadata: Mapping[str, Any], query_tokens: Set[str]) -> float:
        raw = metadata.get(self.field)
        if raw is None:
            return self.default
        if isinstance(raw, (list, tuple, set)):
            best = self.default
            for item in raw:
                best = max(best, self.priorities.get(self._norm(item), self.default))
            return best
        return self.priorities.get(self._norm(raw), self.default)


class MetadataScorer:
    """Weighted blend of metadata ranking rules into a [0, 1] score."""

    def __init__(self, rules: Sequence[Rule]) -> None:
        if not rules:
            raise ValueError("MetadataScorer requires at least one Rule")
        self.rules = list(rules)

    def score(self, metadata: Mapping[str, Any], query: str) -> float:
        query_tokens = set(tokenize(query))
        total_weight = sum(rule.weight for rule in self.rules)
        if total_weight <= 0:
            return 0.0
        acc = sum(rule.weight * rule.score(metadata, query_tokens) for rule in self.rules)
        return max(0.0, min(1.0, acc / total_weight))


# ---------------------------------------------------------------------------
# Combined relevance ranking + optional MMR
# ---------------------------------------------------------------------------

@dataclass
class RetrievalHit:
    document: Document
    score: float          # combined ranking score
    semantic: float       # cosine similarity component
    metadata: float       # metadata relevance component

    def __repr__(self) -> str:  # pragma: no cover - convenience for demos
        return (
            f"RetrievalHit(score={self.score:.3f}, semantic={self.semantic:.3f}, "
            f"metadata={self.metadata:.3f}, doc_id={self.document.doc_id}, "
            f"meta={self.document.metadata})"
        )


class RelevanceRanker:
    """Rank documents by semantic similarity AND metadata relevance."""

    def __init__(
        self,
        index: DocumentIndex,
        scorer: MetadataScorer,
        semantic_weight: float = 0.65,
        metadata_weight: float = 0.35,
    ) -> None:
        if semantic_weight < 0 or metadata_weight < 0:
            raise ValueError("weights must be non-negative")
        self.index = index
        self.scorer = scorer
        self.semantic_weight = float(semantic_weight)
        self.metadata_weight = float(metadata_weight)

    def _score_candidates(self, query: str, docs: Sequence[Document]) -> List[RetrievalHit]:
        query_vec = self.index.query_vector(query)
        hits: List[RetrievalHit] = []
        for doc in docs:
            semantic = _dot(query_vec, self.index.vector_for(doc))
            metadata = self.scorer.score(doc.metadata, query)
            combined = self.semantic_weight * semantic + self.metadata_weight * metadata
            hits.append(RetrievalHit(doc, combined, semantic, metadata))
        hits.sort(key=lambda hit: hit.score, reverse=True)
        return hits

    def retrieve(
        self,
        query: str,
        k: int = 5,
        filters: Optional[MetadataFilters] = None,
        fetch_k: Optional[int] = None,
        mmr_lambda: Optional[float] = None,
    ) -> List[RetrievalHit]:
        """Metadata-filter, then rank, then (optionally) diversify with MMR."""
        if filters is None:
            filters = MetadataFilters()
        candidates = filters.apply(self.index.docs) if not filters.empty else list(self.index.docs)
        scored = self._score_candidates(query, candidates)
        if mmr_lambda is None:
            return scored[:k]
        if not (0.0 <= mmr_lambda <= 1.0):
            raise ValueError("mmr_lambda must be in [0, 1]")
        fetch_k = fetch_k if fetch_k is not None else max(k * 4, 20)
        return self._mmr_select(scored[:fetch_k], k, mmr_lambda)

    def _mmr_select(self, pool: List[RetrievalHit], k: int, mmr_lambda: float) -> List[RetrievalHit]:
        """Greedy Maximal Marginal Relevance: relevance minus redundancy."""
        chosen: List[RetrievalHit] = []
        remaining = list(pool)
        while remaining and len(chosen) < k:
            best_hit, best_value = None, float("-inf")
            for hit in remaining:
                redundancy = 0.0
                for selected in chosen:
                    redundancy = max(
                        redundancy,
                        _dot(
                            self.index.vector_for(hit.document),
                            self.index.vector_for(selected.document),
                        ),
                    )
                mmr = mmr_lambda * hit.score - (1.0 - mmr_lambda) * redundancy
                if mmr > best_value:
                    best_value, best_hit = mmr, hit
            if best_hit is None:
                break
            remaining.remove(best_hit)
            chosen.append(best_hit)
        return chosen


# ---------------------------------------------------------------------------
# Grounded generation (pluggable, local)
# ---------------------------------------------------------------------------

DEFAULT_PROMPT_TEMPLATE = (
    "Answer the question using ONLY the provided contexts. "
    "If the contexts do not contain the answer, reply that you do not have "
    "enough information. Cite each context with its bracket number.\n\n"
    "Contexts:\n{contexts}\n\nQuestion: {question}\n\nAnswer:"
)


def build_context_block(hits: Sequence[RetrievalHit]) -> str:
    lines: List[str] = []
    for i, hit in enumerate(hits, start=1):
        meta_desc = ", ".join(f"{key}={value}" for key, value in hit.document.metadata.items())
        lines.append(f"[{i}] ({meta_desc})\n{hit.document.text.strip()}")
    return "\n\n".join(lines)


def build_prompt(
    question: str,
    hits: Sequence[RetrievalHit],
    template: str = DEFAULT_PROMPT_TEMPLATE,
) -> str:
    return template.format(contexts=build_context_block(hits), question=question)


def generate_answer(
    question: str,
    hits: Sequence[RetrievalHit],
    llm_fn: Optional[Callable[[str], str]] = None,
) -> Optional[str]:
    """Return the grounded answer.

    *llm_fn* is an injectable, user-supplied generator; when it is None the
    function returns None (no network call is ever made by this module).
    """
    if llm_fn is None:
        return None
    return llm_fn(build_prompt(question, hits))


# ---------------------------------------------------------------------------
# High-level pipeline
# ---------------------------------------------------------------------------

class MetadataRagSystem:
    """End-to-end RAG: ingest documents with metadata, then filter + rank."""

    def __init__(
        self,
        index: Optional[DocumentIndex] = None,
        scorer: Optional[MetadataScorer] = None,
        semantic_weight: float = 0.65,
        metadata_weight: float = 0.35,
    ) -> None:
        self.index = index if index is not None else DocumentIndex()
        self.scorer = scorer  # set after rules are chosen by the caller
        self.semantic_weight = semantic_weight
        self.metadata_weight = metadata_weight
        self._ranker: Optional[RelevanceRanker] = None

    # -- ingestion ----------------------------------------------------------
    def ingest(self, documents: Iterable[Document], build: bool = True) -> "MetadataRagSystem":
        self.index.add_many(documents)
        if build:
            self.index.build()
        return self

    def ingest_chunks(
        self,
        text: str,
        metadata: Optional[Mapping[str, Any]] = None,
        chunker: Optional[RecursiveChunker] = None,
        build: bool = True,
    ) -> "MetadataRagSystem":
        chunker = chunker or RecursiveChunker()
        return self.ingest(chunker.split(text, metadata), build=build)

    # -- querying -----------------------------------------------------------
    def _ranker_or_raise(self) -> RelevanceRanker:
        if self.scorer is None:
            raise RuntimeError("set a MetadataScorer (scorer) before querying")
        if self._ranker is None:
            self._ranker = RelevanceRanker(
                self.index,
                self.scorer,
                semantic_weight=self.semantic_weight,
                metadata_weight=self.metadata_weight,
            )
        return self._ranker

    def retrieve(
        self,
        query: str,
        k: int = 5,
        filters: Optional[MetadataFilters] = None,
        **kwargs: Any,
    ) -> List[RetrievalHit]:
        return self._ranker_or_raise().retrieve(query, k=k, filters=filters, **kwargs)

    def query(
        self,
        query: str,
        k: int = 5,
        filters: Optional[MetadataFilters] = None,
        llm_fn: Optional[Callable[[str], str]] = None,
        **retrieve_kwargs: Any,
    ) -> Tuple[Optional[str], List[RetrievalHit]]:
        hits = self.retrieve(query, k=k, filters=filters, **retrieve_kwargs)
        return generate_answer(query, hits, llm_fn=llm_fn), hits


# ---------------------------------------------------------------------------
# Demo corpus + CLI
# ---------------------------------------------------------------------------

def _demo_corpus() -> List[Document]:
    """Build a small, fully local demo corpus with rich metadata."""

    raw = [
        # (text, metadata)
        (
            "Data breach response: containment steps include revoking compromised "
            "credentials, isolating affected systems, preserving logs, and notifying "
            "the security officer within 24 hours.",
            {
                "source": "security-handbook", "category": "security",
                "tags": ["breach", "incident", "credentials"],
                "published_at": "2024-05-02", "confidence": 0.98,
            },
        ),
        (
            "Incident reporting SLA: critical incidents must be logged in the ticketing "
            "system and escalated to the on-call engineer immediately.",
            {
                "source": "faq", "category": "operations",
                "tags": ["incident", "sla", "reporting"],
                "published_at": "2023-11-15", "confidence": 0.70,
            },
        ),
        (
            "Billing cycle policy: invoices are generated on the first business day of "
            "each month; payment terms are net 30 days from the invoice date.",
            {
                "source": "policy-doc", "category": "billing",
                "tags": ["invoice", "payment", "terms"],
                "published_at": "2022-01-10", "confidence": 0.95,
            },
        ),
        (
            "International shipping: orders ship with a carrier-provided tracking number "
            "and duties are calculated at checkout based on destination.",
            {
                "source": "operations-wiki", "category": "support",
                "tags": ["shipping", "tracking", "duties"],
                "published_at": "2023-03-22", "confidence": 0.85,
            },
        ),
        (
            "Password reset security check: verify identity with the registered recovery "
            "email before issuing a reset link; the link expires in 15 minutes.",
            {
                "source": "security-handbook", "category": "security",
                "tags": ["password", "identity", "recovery"],
                "published_at": "2024-01-18", "confidence": 0.93,
            },
        ),
        (
            "Refund policy: unopened products may be returned within 30 days; refunds are "
            "issued to the original payment method within 5 business days.",
            {
                "source": "policy-doc", "category": "billing",
                "tags": ["refund", "returns", "payment"],
                "published_at": "2021-06-30", "confidence": 0.90,
            },
        ),
    ]
    docs: List[Document] = []
    for idx, (text, meta) in enumerate(raw):
        chunk_meta = dict(meta)
        chunk_meta["doc_title"] = f"demo-{idx + 1}"
        docs.append(Document(text=text, metadata=chunk_meta, doc_id=chunk_meta["doc_title"]))
    return docs


def _demo_llm(prompt: str) -> str:
    """Deterministic, local stand-in generator: cites the top context."""
    first_line = prompt.splitlines()[0]
    return f"[local demo response to: {first_line}]"

# NOTE: The rule priorities below are *examples* supplied by the application.
# They rank freshness and authoritative sources higher; swap in any metadata
# policy that fits your domain. Nothing here transmits data off-machine.

def _demo_rag() -> MetadataRagSystem:
    docs = _demo_corpus()
    scorer = MetadataScorer(
        rules=[
            TagOverlapRule(field="tags", weight=1.2),          # query-aware tag overlap
            RecencyRule(date_field="published_at", half_life_days=400, weight=0.8),
            ValuePriorityRule(                                  # authoritative sources
                field="source",
                priorities={
                    "security-handbook": 1.0,
                    "policy-doc": 0.9,
                    "operations-wiki": 0.6,
                    "faq": 0.4,
                },
                weight=0.7,
            ),
        ]
    )
    system = MetadataRagSystem(index=DocumentIndex(), scorer=scorer)
    return system.ingest(docs)


def _print_hits(title: str, hits: Sequence[RetrievalHit]) -> None:
    print(f"\n=== {title} ===")
    if not hits:
        print("(no results)")
        return
    for hit in hits:
        md = hit.document.metadata
        print(
            f"  rank-score {hit.score:+.3f}  semantic {hit.semantic:+.3f}  "
            f"metadata {hit.metadata:+.3f}  [{md.get('doc_title')} | {md.get('category')} | "
            f"{md.get('source')} | {md.get('published_at')}]"
        )


def main() -> None:
    rag = _demo_rag()

    # Example 1: metadata FILTER (only security category) then ranking that
    # prefers fresh, authoritative docs matching query keywords.
    filters = MetadataFilters(include={"category": ["security"]})
    hits = rag.retrieve("how should we respond to a data breach?", k=3, filters=filters)
    _print_hits("filtered: category=security, query='data breach response'", hits)

    # Example 2: same query, no filter -> metadata relevance still boosts
    # the on-topic security doc over topically looser hits.
    hits_all = rag.retrieve("how should we respond to a data breach?", k=3)
    _print_hits("unfiltered: query='data breach response' (metadata ranking active)", hits_all)

    # Example 3: recency range filter over ISO dates.
    date_filter = MetadataFilters(
        ranges={"published_at": ("2023-01-01", None)}
    )
    hits_recent = rag.retrieve("what are our refund or return terms?", k=2, filters=date_filter)
    _print_hits("filtered: published since 2023, query='refund return terms'", hits_recent)

    # Example 4: grounded generation with the injectable local LLM function.
    answer, hits_q = rag.query(
        "what is the billing payment term?",
        k=2,
        llm_fn=_demo_llm,
        filters=MetadataFilters(include={"category": ["billing"]}),
    )
    print("\n=== grounded generation (local demo generator) ===")
    print("  question: what is the billing payment term?")
    print(f"  answer  : {answer}")


if __name__ == "__main__":
    main()

